"""Git status node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError
from ...system_access import checked_path, finish


class GitStatusNode(Node):
    """Branch, clean or not, and changed files of a Git repository (runs git status, nothing else)."""

    node_type: ClassVar[str] = 'git_status_node'
    display_name: ClassVar[str] = 'Git status'
    default_alias: ClassVar[str] = 'Git status'
    description: ClassVar[str] = 'Branch, clean or not, and changed files of a Git repository (runs git status, nothing else)'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Inputs'
    tags: ClassVar[List[str]] = ['System']
    icon_name: ClassVar[str] = 'git-branch'
    color_hint: ClassVar[str] = 'green'
    group: ClassVar[Optional[str]] = 'System'
    selector_section: ClassVar[Optional[str]] = 'System'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Git status', 'description': 'The value chosen in Report: Clean [bool], Branch [string], Changed files [var], Commits ahead [number]', 'data_type': 'any', 'required': True, 'to': ['downstream', 'vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'folder': '~', 'report': 'Clean', 'include_untracked': True, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'folder': {'type': 'string', 'label': 'Folder', 'required': True, 'description': 'Must be inside an allowed folder (Options: system_node_folders)', 'tab': 'Parameters'}, 'report': {'type': 'select', 'label': 'Report', 'options': ['Clean', 'Branch', 'Changed files', 'Commits ahead'], 'tab': 'Parameters'}, 'include_untracked': {'type': 'boolean', 'label': 'Include untracked files', 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'folder_missing', 'description': 'The folder does not exist.', 'retryable': False}, {'code': 'not_allowed', 'description': 'The folder is outside the folders allowed in Options.', 'retryable': False}, {'code': 'not_a_repository', 'description': 'The folder is not inside a Git repository.', 'retryable': False}, {'code': 'git_missing', 'description': 'Git is not installed or not on PATH.', 'retryable': False}, {'code': 'timeout', 'description': 'git status did not finish within 15 seconds.', 'retryable': True}, {'code': 'git_failed', 'description': 'git status failed for another reason (its message is kept).', 'retryable': False}]

    REPORT_TYPES: ClassVar[Dict[str, str]] = {
        "Clean": "bool", "Branch": "string", "Changed files": "var", "Commits ahead": "number"}

    @classmethod
    def describe_output_ports(cls, config: Optional[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        """The output's type follows Report."""
        report = str((config or {}).get("report") or "Clean")
        return {"default": {"data_type": cls.REPORT_TYPES.get(report, "any")}}

    async def execute(self, context: NodeContext) -> None:
        import asyncio
        import shutil

        try:
            folder = checked_path(self.config.get("folder"), context.get_setting)
        except NodeError as exc:
            context.signal_error(exc)
            return
        git = shutil.which("git")
        if git is None:
            context.signal_error(NodeError("git_missing", "Git is not installed or not on PATH"))
            return
        # The command is fixed; only the folder changes. argv, no shell.
        argv = [git, "-C", str(folder), "status", "--porcelain=v2", "--branch",
                "--untracked-files=" + ("normal" if self.config.get("include_untracked", True) else "no")]
        try:
            process = await asyncio.create_subprocess_exec(
                *argv, stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
                stdin=asyncio.subprocess.DEVNULL)
            out, err = await asyncio.wait_for(process.communicate(), timeout=15)
        except asyncio.TimeoutError:
            process.kill()
            await process.wait()
            context.signal_error(NodeError("timeout", "git status did not finish within 15 seconds"))
            return
        if process.returncode != 0:
            message = err.decode("utf-8", "replace").strip()
            code = "not_a_repository" if "not a git repository" in message.lower() else "git_failed"
            context.signal_error(NodeError(code, message or f"git status exited {process.returncode}"))
            return
        branch, ahead, changed = "", 0, []
        for line in out.decode("utf-8", "replace").splitlines():
            if line.startswith("# branch.head "):
                branch = line.split(" ", 2)[2]
            elif line.startswith("# branch.ab "):
                ahead = int(line.split()[2].lstrip("+") or 0)
            elif line[:2] in ("1 ", "2 ", "u "):
                changed.append(line.split(" ")[-1] if line[0] != "2" else line.split("\t")[0].split(" ")[-1])
            elif line.startswith("? "):
                changed.append(line[2:])
        report = str(self.config.get("report") or "Clean")
        value = {"Clean": not changed, "Branch": branch, "Changed files": changed,
                 "Commits ahead": ahead}.get(report, not changed)
        finish(self, context, value, self.REPORT_TYPES.get(report, "var"))
